    // Structure
    structureTitle: 'Anatomy of a skill folder',
    structureSubtitle: 'What the specification defines',
    treeSkillMd: 'required: frontmatter + instructions',
    treeScripts: 'optional: executable code',
    treeReferences: 'optional: documentation read on demand',
    treeAssets: 'optional: templates, schemas, images',
    structureNote: "Only SKILL.md is required. The folder name must match the name field. Reference files should be linked directly from SKILL.md, one level deep, rather than through long chains of references.",
    frontmatterTitle: 'Frontmatter fields',
    fieldCol: 'Field',
    requiredCol: 'Required',
    ruleCol: 'Rule',
    fields: [
      { field: 'name', required: 'yes', rule: "Up to 64 characters: lowercase letters, digits and single hyphens. Must match the folder name." },
      { field: 'description', required: 'yes', rule: "Up to 1,024 characters. States what the skill does and when to use it." },
      { field: 'license', required: 'no', rule: "License name or a reference to a bundled license file." },
      { field: 'compatibility', required: 'no', rule: "Up to 500 characters. Environment requirements such as system packages or network access." },
      { field: 'metadata', required: 'no', rule: "Free key-value pairs, for example author and version." },
      { field: 'allowed-tools', required: 'no', rule: "Experimental: space-separated list of pre-approved tools. Support varies between clients." },
    ],
    fieldsNote: "Clients add their own fields. Claude Code, for example, supports disable-model-invocation, which allows a skill to be started only manually via a slash command. Such fields are not portable to other clients.",

    // Selection
    selectionTitle: 'How the description controls selection',
    selectionP1: "In most implementations no keyword matcher decides which skill is used. The model reads the catalog and judges whether a description fits the current task. The description is therefore the only part of a skill that is always in context, and it has to answer two questions: what does the skill do, and when should it be used?",
    selectionP2: "Users can also start a skill explicitly, typically with a slash command such as /code-review. The host then injects the instructions directly, without the model having to choose.",
    goodLabel: 'Specific',
    poorLabel: 'Too vague',
    goodExample: "Extracts text and tables from PDF files, fills PDF forms and merges multiple PDFs. Use when working with PDF documents or when the user mentions PDFs, forms or document extraction.",
    poorExample: 'Helps with PDFs.',
    selectionNote: "A vague description causes two kinds of error: the skill is not loaded when it would help, or it is loaded for unrelated tasks and wastes context.",

    // Comparison
    compareTitle: 'Skills, tools, MCP and subagents',
    compareDesc: "\"Skills are knowledge, tools are actions\" is too simple: a skill can bundle scripts and thereby trigger actions. The real difference is where something lives and how it reaches the model.",
    colConcept: 'Concept',
    colWhat: 'What it is',
    colContext: 'What enters the context',
    colRuns: 'Who executes',
    compareRows: [
      { concept: 'Skill', what: 'Folder with instructions, scripts and files', context: 'Catalog entry; body and files only on activation', runs: 'The agent, using tools it already has, such as file reading and the shell' },
      { concept: 'Tool', what: 'Callable function with name, description and input schema', context: 'Definition in every request, result after each call', runs: 'The host or a server, when the model calls it' },
      { concept: 'MCP server', what: 'Program that offers tools, resources and prompts over a protocol', context: 'Its tool definitions, like any other tools', runs: 'The server process, local or remote' },
      { concept: 'Subagent', what: 'Separate model instance with its own context window', context: 'Only the task goes in, only a summary comes back', runs: 'A second agent loop' },
    ],
    compareNote: "They combine: a skill can tell the agent which MCP tools to call in which order, and some hosts can run a skill inside a subagent. Claude Code does this with context: fork, so the skill's intermediate steps do not fill the main context.",

    // Types of skills
    typesTitle: 'Common kinds of skills',
    skillType1Title: 'Domain skills',
    skillType1Desc: "Domain-specific references and procedures. They support specialised work but do not replace domain expertise or checking the evidence.",
    skillType2Title: 'Workflow skills',
    skillType2Desc: 'Multi-step processes with defined stages, such as code review, publishing pipelines or incident response.',
    skillType3Title: 'Format skills',
    skillType3Desc: 'Consistent output formats, such as API documentation, changelog entries or meeting summaries, often with a template in assets/.',
    skillType4Title: 'Integration skills',
    skillType4Desc: "Instructions for a specific tool or service, for example which MCP tools to call in which order and which fields a Jira ticket needs.",

    // Security
    securityTitle: 'Supply-chain risk: skills are software',
    securityP1: "A skill runs with the agent's permissions. Its instructions steer the model, and its scripts run in the shell. A malicious skill can therefore read files, exfiltrate credentials or install malware without exploiting a single code vulnerability.",
    securityP2: "This has already happened at scale. In early 2026, Koi Security found 341 malicious skills on ClawHub, the skill marketplace of the open-source agent OpenClaw. A common pattern was a fake prerequisites section in SKILL.md that told the agent to decode a Base64 string and pipe it to bash, which then downloaded the actual payload.",
    securityChecksTitle: 'Checklist before installing a skill',
    securityChecks: [
      'Read every file: SKILL.md, scripts, references and assets.',
      'Look for network calls, encoded commands and instructions that do not match the stated purpose.',
      'Pin skills to a reviewed version or commit; linked external content can change after the review.',
      'Load project-level skills from cloned repositories only if the folder is trusted.',
      'Run agents with minimal permissions and in a sandbox; allowed-tools widens what runs without confirmation.',
    ],

    // Example
    exampleTitle: 'Example: a complete SKILL.md',
    exampleDesc: "Reviews code changes for correctness, security and test coverage. Use when the user asks for a review of a diff, pull request or file.",
