    exampleTreeNote: "Next to it: scripts/run_checks.sh and references/checklist.md, loaded only when step 2 or step 3 is reached.",

    // Best practices
    practicesTitle: 'Best practices',
    practices: [
      { title: 'Write the description for selection', desc: "Name the task and the situations that should trigger the skill, using the words users actually use. It is the only text that is always in context." },
      { title: 'Keep SKILL.md short', desc: "Stay under 500 lines. Move details into references/ and link them directly from SKILL.md, one level deep." },
      { title: 'Use scripts for deterministic steps', desc: "Validation, conversion and checks run more reliably as code than as instructions the model has to reproduce, and only their output costs context." },
      { title: 'Test and version skills', desc: "Check with real tasks whether the skill is selected and followed, and keep it under version control so behaviour changes can be traced to a skill update." },
    ],

    // Key Takeaways
    keyTakeaways: 'Key takeaways',
    takeaway1: 'A skill is a folder: SKILL.md with name, description and instructions, plus optional scripts/, references/ and assets/.',
