    useCase3: "Anything where the 1M context actually matters: entire codebases, long conversations, extensive documentation",
    useCase4: "Tasks where adaptive thinking steps matter — Fable 5 always reasons, whether you want it to or not",
    useCase5: "Anything where I want the absolute most capable model and cost is secondary",

    // Pricing
    pricingTitle: "The Pricing Reality",
    pricingSubtitle: "Fable 5 is expensive — twice the price of Opus 4.8.",
    pricingModelTitle: "Claude Fable 5",
    pricingModelDetail: "$10 input / $50 output per million tokens. Double the price of Opus 4.8 ($5/$25). Prompt caching gives 90% off input tokens. No premium for the full 1M context window. A heavy coding session can run $10-30.",
    pricingVerdict: "Honest take: At $10/$50, Fable 5 is a premium tool. But if one hour of Fable 5 saves a week of developer time — because it handles tasks in one pass that Opus 4.8 needs three attempts at — then it's cheap.",

    // Verdict
    verdictTitle: "The Honest Verdict",
    verdictText: "Claude Fable 5 is the first model where I say: this is a genuine leap, not just an incremental update. 95% SWE-bench Verified, 1M context, 128K output, Mythos-class architecture. It's exactly what I want: a model that can think across long tasks, self-verify, and code at a level that outclasses everything before it. The fact that it's currently offline doesn't make it less my favourite — it makes clear how valuable it is. When it comes back, it's my default.",

