    getKeyDesc: 'This guide uses a single path: OpenRouter with its Free Models Router. One key gives you access to many models, and the router picks a free one for you, so you do not need to compare providers or model IDs yet.',
    routerName: 'OpenRouter · Free Models Router',
    openrouterAutoOnlyDesc: 'The model ID openrouter/free sends your request to a randomly chosen free model that supports the features your request needs. The response field model tells you which one actually answered.',
