    freeTierRandomModel: 'The router chooses at random from the current free pool. Two requests in the same conversation can be answered by different models, so tone and quality may change between turns.',
    freeTierPrivacy: 'Free endpoints are run by providers with their own data policies; some may log your prompts or use them for training. OpenRouter has separate privacy settings for free and paid models in your account. Do not send personal or confidential data through free endpoints.',
